-- Django-compatible tables preserve IDs, relationships, and migration fidelity.
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "account_emailconfirmation" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created" datetime NOT NULL, "sent" datetime NULL, "key" varchar(64) NOT NULL UNIQUE, "email_address_id" integer NOT NULL REFERENCES "account_emailaddress" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "account_emailaddress" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "verified" bool NOT NULL, "primary" bool NOT NULL, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "email" varchar(254) NOT NULL);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE "hub_revision" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "snapshot" text NOT NULL CHECK ((JSON_VALID("snapshot") OR "snapshot" IS NULL)), "created_at" datetime NOT NULL, "editor_id" integer NULL REFERENCES "auth_user" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, "item_id" char(32) NOT NULL REFERENCES "hub_item" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "hub_screenshot" ("id" char(32) NOT NULL PRIMARY KEY, "image" varchar(100) NOT NULL, "caption" varchar(180) NOT NULL, "created_at" datetime NOT NULL, "item_id" char(32) NOT NULL REFERENCES "hub_item" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "hub_bookmark" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "item_id" char(32) NOT NULL REFERENCES "hub_item" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "unique_bookmark" UNIQUE ("user_id", "item_id"));
CREATE TABLE "hub_contenttype" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(50) NOT NULL, "slug" varchar(50) NOT NULL UNIQUE, "description" varchar(200) NOT NULL, "allowed_extensions" text NOT NULL CHECK ((JSON_VALID("allowed_extensions") OR "allowed_extensions" IS NULL)), "position" integer unsigned NOT NULL CHECK ("position" >= 0), "uploads_enabled" bool NOT NULL);
CREATE TABLE "hub_apikey" ("id" char(32) NOT NULL PRIMARY KEY, "name" varchar(80) NOT NULL, "prefix" varchar(16) NOT NULL UNIQUE, "digest" varchar(64) NOT NULL, "scopes" text NOT NULL CHECK ((JSON_VALID("scopes") OR "scopes" IS NULL)), "created_at" datetime NOT NULL, "last_used_at" datetime NULL, "revoked_at" datetime NULL, "application_id" bigint NULL REFERENCES "oauth2_provider_application" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "expires_at" datetime NULL);
CREATE TABLE "hub_userpreferences" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "ugc_warning_version" smallint unsigned NOT NULL CHECK ("ugc_warning_version" >= 0), "ugc_warning_acknowledged_at" datetime NULL, "user_id" integer NOT NULL UNIQUE REFERENCES "auth_user" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "hub_filedeletion" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(1024) NOT NULL UNIQUE, "created_at" datetime NOT NULL);
CREATE TABLE "hub_moderationlog" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "item_title" varchar(100) NOT NULL, "username" varchar(150) NOT NULL, "action" varchar(40) NOT NULL, "reason" text NOT NULL, "created_at" datetime NOT NULL, "actor_id" integer NULL REFERENCES "auth_user" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, "item_id" char(32) NULL REFERENCES "hub_item" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, "target_user_id" integer NULL REFERENCES "auth_user" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "hub_usermoderation" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "shadow_banned_at" datetime NULL, "shadow_banned_by_id" integer NULL REFERENCES "auth_user" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL UNIQUE REFERENCES "auth_user" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "hub_accountactivity" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "item_title" varchar(100) NOT NULL, "action" varchar(20) NOT NULL, "ip_address" char(39) NULL, "ip_source" varchar(12) NOT NULL, "user_agent" varchar(1024) NOT NULL, "accept_language" varchar(256) NOT NULL, "auth_method" varchar(32) NOT NULL, "provider_uid" varchar(255) NOT NULL, "request_path" varchar(255) NOT NULL, "cf_ray" varchar(80) NOT NULL, "created_at" datetime NOT NULL, "item_id" char(32) NULL REFERENCES "hub_item" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "hub_itemreview" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_revision" bigint unsigned NOT NULL CHECK ("content_revision" >= 0), "note" text NOT NULL, "created_at" datetime NOT NULL, "item_id" char(32) NOT NULL REFERENCES "hub_item" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "reviewer_id" integer NULL REFERENCES "auth_user" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "unique_item_review_revision" UNIQUE ("item_id", "content_revision"));
CREATE TABLE "hub_downloadip" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "network" varchar(43) NOT NULL, "expires_at" datetime NOT NULL, "item_id" char(32) NOT NULL REFERENCES "hub_item" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "release_id" char(32) NULL REFERENCES "hub_release" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "hub_downloaduser" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "item_id" char(32) NOT NULL REFERENCES "hub_item" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "release_id" char(32) NULL REFERENCES "hub_release" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "hub_uploadevent" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "hub_tag" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(600) NOT NULL UNIQUE);
CREATE TABLE "hub_item_tag_index" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "item_id" char(32) NOT NULL REFERENCES "hub_item" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "tag_id" bigint NOT NULL REFERENCES "hub_tag" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "hub_tagsettings" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "minimum_items" integer unsigned NOT NULL CHECK ("minimum_items" >= 0), CONSTRAINT "single_valid_tag_settings" CHECK (("minimum_items" >= 1 AND "id" = 1)));
CREATE TABLE "hub_item" ("id" char(32) NOT NULL PRIMARY KEY, "title" varchar(100) NOT NULL, "summary" varchar(180) NOT NULL, "description" text NOT NULL, "tags" varchar(200) NOT NULL, "status" varchar(12) NOT NULL, "is_demo" bool NOT NULL, "artwork" smallint unsigned NOT NULL CHECK ("artwork" >= 0), "downloads" integer unsigned NOT NULL CHECK ("downloads" >= 0), "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "author_id" integer NOT NULL REFERENCES "auth_user" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "content_type_id" bigint NOT NULL REFERENCES "hub_contenttype" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED, "featured_at" datetime NULL, "featured_by_id" integer NULL REFERENCES "auth_user" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, "hidden_at" datetime NULL, "hidden_by_id" integer NULL REFERENCES "auth_user" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, "hidden_reason" text NOT NULL, "is_hidden" bool NOT NULL, "deleted_at" datetime NULL, "content_revision" bigint unsigned NOT NULL CHECK ("content_revision" >= 0), "review_requested_at" datetime NOT NULL, "reviewed_revision" bigint unsigned NOT NULL CHECK ("reviewed_revision" >= 0), "publish_after_validation" bool NOT NULL, CONSTRAINT "hidden_item_requires_reason" CHECK ((NOT "is_hidden" OR NOT ("hidden_reason" = ''))));
CREATE TABLE "hub_uploadjob" ("id" char(32) NOT NULL PRIMARY KEY, "kind" varchar(12) NOT NULL, "status" varchar(12) NOT NULL, "original_filename" varchar(255) NOT NULL, "size" bigint unsigned NOT NULL CHECK ("size" >= 0), "sha256" varchar(64) NOT NULL, "metadata" text NOT NULL CHECK ((JSON_VALID("metadata") OR "metadata" IS NULL)), "error" varchar(300) NOT NULL, "created_at" datetime NOT NULL, "completed_at" datetime NULL, "item_id" char(32) NOT NULL REFERENCES "hub_item" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "release_id" char(32) NULL REFERENCES "hub_release" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, "screenshot_id" char(32) NULL REFERENCES "hub_screenshot" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, "submitted_by_id" integer NULL REFERENCES "auth_user" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "hub_uploadsettings" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "max_file_mb" integer unsigned NOT NULL CHECK ("max_file_mb" >= 0), CONSTRAINT "single_valid_upload_settings" CHECK (("max_file_mb" >= 1 AND "max_file_mb" <= 100 AND "id" = 1)));
CREATE TABLE "hub_release" ("id" char(32) NOT NULL PRIMARY KEY, "version" varchar(40) NOT NULL, "game_version" varchar(40) NOT NULL, "changelog" text NOT NULL, "file" varchar(100) NOT NULL, "original_filename" varchar(255) NOT NULL, "sha256" varchar(64) NOT NULL, "size" bigint unsigned NOT NULL CHECK ("size" >= 0), "downloads" integer unsigned NOT NULL CHECK ("downloads" >= 0), "created_at" datetime NOT NULL, "item_id" char(32) NOT NULL REFERENCES "hub_item" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "file_stats" text NOT NULL CHECK ((JSON_VALID("file_stats") OR "file_stats" IS NULL)), CONSTRAINT "unique_item_release_version" UNIQUE ("item_id", "version"));
CREATE TABLE "hub_sitemapstate" ("id" smallint unsigned NOT NULL PRIMARY KEY CHECK ("id" >= 0), "generated_at" datetime NOT NULL);
CREATE TABLE "hub_sitemapentry" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "path" varchar(300) NOT NULL UNIQUE, "last_modified" datetime NULL, "author_id" integer NULL REFERENCES "auth_user" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, "item_id" char(32) NULL REFERENCES "hub_item" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "hub_storageusage" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "backend" varchar(20) NOT NULL, "object_count" bigint unsigned NOT NULL CHECK ("object_count" >= 0), "size_bytes" bigint unsigned NOT NULL CHECK ("size_bytes" >= 0), "measured_at" datetime NOT NULL);
CREATE TABLE "oauth2_provider_idtoken" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "jti" char(32) NOT NULL UNIQUE, "expires" datetime NOT NULL, "scope" text NOT NULL, "created" datetime NOT NULL, "updated" datetime NOT NULL, "application_id" bigint NULL REFERENCES "oauth2_provider_application" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, "user_id" integer NULL REFERENCES "auth_user" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "oauth2_provider_devicegrant" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "device_code" varchar(100) NOT NULL, "user_code" varchar(100) NOT NULL, "interval" integer NOT NULL, "expires" datetime NOT NULL, "status" varchar(64) NOT NULL, "client_id" varchar(100) NOT NULL, "last_checked" datetime NOT NULL, "user_id" integer NULL REFERENCES "auth_user" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, "scope" text NOT NULL, CONSTRAINT "oauth2_provider_devicegrant_unique_device_code" UNIQUE ("device_code"));
CREATE TABLE "oauth2_provider_accesstoken" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "token" text NOT NULL, "expires" datetime NOT NULL, "scope" text NOT NULL, "application_id" bigint NULL REFERENCES "oauth2_provider_application" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, "user_id" integer NULL REFERENCES "auth_user" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, "created" datetime NOT NULL, "updated" datetime NOT NULL, "source_refresh_token_id" bigint NULL UNIQUE REFERENCES "oauth2_provider_refreshtoken" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, "id_token_id" bigint NULL UNIQUE REFERENCES "oauth2_provider_idtoken" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, "token_checksum" varchar(64) NOT NULL UNIQUE, "resource" text NOT NULL CHECK ((JSON_VALID("resource") OR "resource" IS NULL)));
CREATE TABLE "oauth2_provider_grant" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(255) NOT NULL UNIQUE, "expires" datetime NOT NULL, "redirect_uri" text NOT NULL, "scope" text NOT NULL, "application_id" bigint NOT NULL REFERENCES "oauth2_provider_application" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "created" datetime NOT NULL, "updated" datetime NOT NULL, "code_challenge" varchar(128) NOT NULL, "code_challenge_method" varchar(10) NOT NULL, "nonce" varchar(255) NOT NULL, "claims" text NOT NULL, "resource" text NOT NULL CHECK ((JSON_VALID("resource") OR "resource" IS NULL)));
CREATE TABLE "oauth2_provider_refreshtoken" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "token" text NOT NULL, "access_token_id" bigint NULL UNIQUE REFERENCES "oauth2_provider_accesstoken" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, "application_id" bigint NOT NULL REFERENCES "oauth2_provider_application" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "created" datetime NOT NULL, "updated" datetime NOT NULL, "revoked" datetime NULL, "token_family" char(32) NULL, "token_checksum" varchar(64) NOT NULL, "resource" text NOT NULL CHECK ((JSON_VALID("resource") OR "resource" IS NULL)));
CREATE TABLE "oauth2_provider_application" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "redirect_uris" text NOT NULL, "client_type" varchar(32) NOT NULL, "authorization_grant_type" varchar(44) NOT NULL, "client_secret" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "user_id" integer NULL REFERENCES "auth_user" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, "skip_authorization" bool NOT NULL, "created" datetime NOT NULL, "updated" datetime NOT NULL, "algorithm" varchar(5) NOT NULL, "post_logout_redirect_uris" text NOT NULL, "hash_client_secret" bool NOT NULL, "allowed_origins" text NOT NULL, "registration_source" varchar(32) NOT NULL, "cimd_expires_at" datetime NULL, "client_id" varchar(255) NOT NULL UNIQUE);
CREATE TABLE "openid_openidnonce" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "server_url" varchar(255) NOT NULL, "timestamp" integer NOT NULL, "salt" varchar(255) NOT NULL, "date_created" datetime NOT NULL);
CREATE TABLE "openid_openidstore" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "server_url" varchar(255) NOT NULL, "handle" varchar(255) NOT NULL, "secret" text NOT NULL, "issued" integer NOT NULL, "lifetime" integer NOT NULL, "assoc_type" text NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE "socialaccount_socialapp" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "provider" varchar(30) NOT NULL, "name" varchar(40) NOT NULL, "client_id" varchar(191) NOT NULL, "secret" varchar(191) NOT NULL, "key" varchar(191) NOT NULL, "provider_id" varchar(200) NOT NULL, "settings" text NOT NULL CHECK ((JSON_VALID("settings") OR "settings" IS NULL)));
CREATE TABLE "socialaccount_socialtoken" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "token" text NOT NULL, "token_secret" text NOT NULL, "expires_at" datetime NULL, "account_id" integer NOT NULL REFERENCES "socialaccount_socialaccount" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "app_id" integer NULL REFERENCES "socialaccount_socialapp" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "socialaccount_socialaccount" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "provider" varchar(200) NOT NULL, "uid" varchar(191) NOT NULL, "last_login" datetime NOT NULL, "date_joined" datetime NOT NULL, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "extra_data" text NOT NULL CHECK ((JSON_VALID("extra_data") OR "extra_data" IS NULL)));
